import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

async function sql(){ return (await readFile(new URL('../../migrations/001_clp001_q.sql', import.meta.url),'utf8')).replace(/\s+/g,' ').toLowerCase(); }

test('migration defines append-only CLP tables and aggregate/idempotency uniqueness', async()=>{
  const s=await sql();
  for(const table of ['clp_events','clp_evidence','clp_versions','clp_commands','clp_chain','clp_lineage','clp_certifications']) assert.match(s,new RegExp(`create table if not exists ${table}`));
  assert.match(s,/unique\s*\(aggregate_id,\s*aggregate_version\)/);
  assert.match(s,/clp_commands\s*\([^]*command_id\s+text\s+primary key/);
  assert.match(s,/clp_versions\s*\([^]*version_ref\s+text\s+primary key/);
  assert.match(s,/clp_versions\s*\([^]*canonical_hash\s+text\s+not null/);
  assert.match(s,/unique\s*\(correlation_id,\s*ordinal\)/);
});

test('migration preserves immutable hashes and correlation query indexes', async()=>{
  const s=await sql();
  assert.match(s,/event_hash\s+text\s+not null/);
  assert.match(s,/content_hash\s+text\s+not null/);
  assert.match(s,/chain_hash\s+text\s+not null/);
  assert.match(s,/create index if not exists idx_clp_events_correlation/);
  assert.match(s,/create index if not exists idx_clp_evidence_correlation/);
  assert.match(s,/create index if not exists idx_clp_lineage_correlation/);
});

test('migration enforces append-only mutation rejection in the database', async()=>{
  const s=await sql();
  assert.match(s,/create or replace function clp_reject_mutation/);
  for(const table of ['clp_events','clp_evidence','clp_versions','clp_commands','clp_chain','clp_lineage','clp_certifications']) assert.match(s,new RegExp(`create trigger ${table}_append_only`));
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { buildGoldenCase, hashCanonical } from '../../dist/src/index.js';
import { ReferenceTransactionalStore } from '../../dist/src/q-reference-store.js';
import { PgTransactionalStore } from '../../dist/src/q-postgres-store.js';

function bundle(commandId='cmd-1'){
  const g=buildGoldenCase();
  return {
    command_id: commandId,
    request_hash: hashCanonical({commandId,event:g.events[0]}),
    event:g.events[0],
    evidence:g.evidence.slice(0,2),
    versions:Object.entries(g.versions).slice(0,1).map(([ref,record])=>({ref,record})),
    chain:[g.event_chain[0]],
    lineage:g.lineage_nodes.filter(n=>['ev_RESIDENT_STATEMENT','ev_RESIDENT_PHOTO'].includes(n.id)),
    certifications:[]
  };
}

test('atomic append commits complete bundle and persists version fingerprint', async()=>{
  const store=new ReferenceTransactionalStore();
  const b=bundle();
  const r=await store.appendBundle(b);
  assert.equal(r.status,'APPENDED');
  const snap=store.backup();
  assert.equal(snap.store.events.length,1);
  assert.equal(snap.store.evidence.length,2);
  const ref=b.versions[0].ref;
  assert.equal(snap.store.version_hashes[ref],hashCanonical(b.versions[0].record));
  assert.equal(snap.command_request_hashes[0][0],'cmd-1');
});

test('bundle failure rolls back every staged write', async()=>{
  const store=new ReferenceTransactionalStore();
  const before=store.backup();
  const b=bundle();
  b.chain[0]={...b.chain[0],event_hash:'sha256:tampered'};
  await assert.rejects(store.appendBundle(b),/chain event hash mismatch/);
  assert.deepEqual(store.backup(),before);
});

test('idempotency key repeats same request but conflicts on different request', async()=>{
  const store=new ReferenceTransactionalStore();
  const b=bundle('cmd-idem');
  assert.equal((await store.appendBundle(b)).status,'APPENDED');
  assert.equal((await store.appendBundle(b)).status,'IDEMPOTENT_REPLAY');
  const other=bundle('cmd-idem');
  other.request_hash=hashCanonical({different:true});
  await assert.rejects(store.appendBundle(other),/idempotency key conflict/);
});

test('aggregate version uniqueness rejects competing event', async()=>{
  const store=new ReferenceTransactionalStore();
  const a=bundle('cmd-a');
  await store.appendBundle(a);
  const b=bundle('cmd-b');
  b.event={...b.event,event_id:'evt_competing'};
  const payload={...b.event}; delete payload.event_hash; b.event.event_hash=hashCanonical(payload);
  b.request_hash=hashCanonical({event:b.event});
  b.chain=[]; b.evidence=[]; b.versions=[]; b.lineage=[];
  await assert.rejects(store.appendBundle(b),/aggregate version conflict/);
});

test('postgres transaction issues rollback when a staged statement fails', async()=>{
  const log=[];
  const client={
    async query(sql,params){ log.push(String(sql).trim().split(/\s+/).slice(0,3).join(' ')); if(String(sql).includes('INSERT INTO clp_events')) throw new Error('db fail'); return {rows:[],rowCount:1}; },
    release(){ log.push('RELEASE'); }
  };
  const pool={async connect(){return client;}};
  const store=new PgTransactionalStore(pool);
  await assert.rejects(store.appendBundle(bundle()),/db fail/);
  assert.ok(log.some(x=>x.startsWith('BEGIN ISOLATION LEVEL')));
  assert.ok(log.includes('ROLLBACK'));
  assert.equal(log.at(-1),'RELEASE');
});

test('postgres durable store exposes current state reads for transport boundary', async()=>{
  const client={async query(sql){if(String(sql).includes('ORDER BY aggregate_version DESC')) return {rows:[{decision:'VERIFIED'}],rowCount:1}; return {rows:[],rowCount:0};},release(){}};
  const store=new PgTransactionalStore({async connect(){return client;}});
  assert.equal(await store.caseState('corr-db'),'VERIFIED');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { buildGoldenCase, hashCanonical } from '../../dist/src/index.js';
import { ReferenceTransactionalStore } from '../../dist/src/q-reference-store.js';
import { encodeBackup, decodeBackup, restoreAndVerifyReplay } from '../../dist/src/q-recovery.js';

function eventBundle(g,i,commandId){
  const ev=g.events[i];
  return {
    command_id:commandId,
    request_hash:hashCanonical({commandId,event:ev}),
    event:ev,
    evidence:i===0?g.evidence:[],
    versions:i===0?Object.entries(g.versions).map(([ref,record])=>({ref,record})):[],
    chain:[g.event_chain[i]],
    lineage:i===g.events.length-1?g.lineage_nodes:[],
    certifications:[]
  };
}
async function seedGolden(){
  const g=buildGoldenCase(); const store=new ReferenceTransactionalStore();
  for(let i=0;i<g.events.length;i++) await store.appendBundle(eventBundle(g,i,`golden-${i+1}`));
  return {g,store};
}

test('concurrent writers for same aggregate version allow exactly one commit', async()=>{
  const g=buildGoldenCase(); const store=new ReferenceTransactionalStore();
  const a=eventBundle(g,0,'race-a');
  const b=structuredClone(a); b.command_id='race-b'; b.event.event_id='evt_race_b'; const payload={...b.event};delete payload.event_hash;b.event.event_hash=hashCanonical(payload);b.request_hash=hashCanonical({event:b.event});b.chain=[];
  const results=await Promise.allSettled([store.appendBundle(a),store.appendBundle(b)]);
  assert.equal(results.filter(r=>r.status==='fulfilled').length,1);
  assert.equal(results.filter(r=>r.status==='rejected').length,1);
  assert.match(String(results.find(r=>r.status==='rejected').reason),/aggregate version conflict/);
  assert.equal(store.backup().store.events.length,1);
});

test('restart from backup preserves replay hash and version fingerprints', async()=>{
  const {g,store}=await seedGolden();
  const before=store.replay(g.correlation_id);
  const restarted=ReferenceTransactionalStore.restore(store.backup());
  const after=restarted.replay(g.correlation_id);
  assert.equal(after.replay_hash,before.replay_hash);
  assert.deepEqual(restarted.backup().store.version_hashes,store.backup().store.version_hashes);
});

test('backup encode/decode restore yields replay-equivalent state', async()=>{
  const {g,store}=await seedGolden();
  const encoded=encodeBackup(store.backup());
  const decoded=decodeBackup(encoded);
  const verified=restoreAndVerifyReplay(decoded,g.correlation_id,store.replay(g.correlation_id).replay_hash);
  assert.equal(verified.replay_hash,store.replay(g.correlation_id).replay_hash);
});

test('backup corruption is rejected before restore', async()=>{
  const {store}=await seedGolden();
  const encoded=JSON.parse(encodeBackup(store.backup()));
  encoded.payload.store.events[0].decision='CLOSED';
  await assert.rejects(async()=>decodeBackup(JSON.stringify(encoded)),/backup hash mismatch/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { hashCanonical } from '../../dist/src/index.js';
import { ReferenceTransactionalStore } from '../../dist/src/q-reference-store.js';
import { QKernelService } from '../../dist/src/q-service.js';
import { createTransportHandler } from '../../dist/src/q-transport.js';
import { authorizeTransition, evaluateEligibility } from '../../input/BUILD-CLP-001-B/dist/src/index.js';

const policy=JSON.parse(fs.readFileSync(new URL('../../input/BUILD-CLP-001-B/input/BUILD-CLP-001-A/fixtures/transition-policy.json', import.meta.url),'utf8'));
function event(decision='INTAKE_STRUCTURED'){
  const payload={event_id:'evt-q-1',event_type:'IssueIntakeStructured',occurred_at:'2026-10-04T10:00:00.000Z',actor_id:'SYSTEM',actor_type:'SYSTEM',aggregate_id:'CASE-Q',aggregate_version:1,causation_event_id:null,correlation_id:'corr-q',input_refs:[],output_refs:[],source_refs:[],policy_refs:['CLP-001-TRANSITIONS@1.0.0'],evidence_refs:[],decision,reason_code:null};
  return {...payload,event_hash:hashCanonical(payload)};
}
function service(){return new QKernelService(new ReferenceTransactionalStore(),policy,{authorizeTransition,evaluateEligibility});}
function transitionBody(decision='INTAKE_STRUCTURED'){
  const ev=event(decision);
  const cr={ordinal:1,event_id:ev.event_id,event_hash:ev.event_hash,previous_chain_hash:null}; const chain={...cr,chain_hash:hashCanonical({...cr,correlation_id:ev.correlation_id})}; return {from:'REPORTED',to:'INTAKE_STRUCTURED',satisfied_guards:['resident_origin_evidence_present'],bundle:{command_id:'cmd-q-1',request_hash:hashCanonical({event:ev}),event:ev,evidence:[],versions:[{ref:'CLP-001-TRANSITIONS@1.0.0',record:policy}],chain:[chain],lineage:[],certifications:[]}};
}

test('transport delegates valid transition through frozen kernel and persists atomically', async()=>{
  const handler=createTransportHandler(service());
  const r=await handler({method:'POST',path:'/v1/clp001/transitions',body:transitionBody()});
  assert.equal(r.status,200);
  assert.equal(r.body.status,'APPENDED');
  const state=await handler({method:'GET',path:'/v1/clp001/cases/corr-q/state'});
  assert.equal(state.body.state,'INTAKE_STRUCTURED');
});

test('transport cannot bypass frozen transition guards', async()=>{
  const handler=createTransportHandler(service());
  const body=transitionBody('CLOSED');
  await assert.doesNotReject(async()=>{
    const r=await handler({method:'POST',path:'/v1/clp001/transitions',body});
    assert.equal(r.status,409);
    assert.match(r.body.error,/event decision mismatch/);
  });
});

test('raw persistence write routes are not exposed', async()=>{
  const handler=createTransportHandler(service());
  for(const path of ['/v1/clp001/events','/v1/clp001/evidence','/v1/clp001/versions','/internal/db/write']){
    const r=await handler({method:'POST',path,body:{}});
    assert.equal(r.status,404);
  }
});

test('replay endpoint returns persisted replay only through service boundary', async()=>{
  const s=service(); const handler=createTransportHandler(s);
  await handler({method:'POST',path:'/v1/clp001/transitions',body:transitionBody()});
  const r=await handler({method:'GET',path:'/v1/clp001/cases/corr-q/replay'});
  assert.equal(r.status,200);
  assert.equal(r.body.correlation_id,'corr-q');
});
